static DISCRETE_8_PRO_SC_RAW_PROFILE: &str = "{\n  \"device\": {\n    \"name\": \"Antelope Discrete 8 Pro Synergy Core\",\n    \"vid\": \"0x23e5\",\n    \"pid\": \"0xa2b5\",\n    \"bcdDevice\": \"02.01\",\n    \"status\": \"confirmed\",\n    \"notes\": \"Composite USB device; control is entirely via the vendor HID interface (iface 3, MI_03), same interface number as Orion Studio III. The UAC2 audio interfaces are separate device nodes and are unaffected by anything in this profile. vid is now independently confirmed for this device, not inherited.\",\n    \"evidence\": \"lsusb and dmesg on Linux, 2026-08; usb ids cross-checked against the Windows PnP database\"\n  },\n  \"transport\": {\n    \"type\": \"hid\",\n    \"report_size\": 320,\n    \"out_endpoint\": \"0x01\",\n    \"in_endpoint\": \"0x82\",\n    \"poll_interval_ms\": 4,\n    \"uses_numbered_reports\": false,\n    \"status\": \"confirmed\",\n    \"notes\": \"Identical to Orion Studio III on every field, so the transport layer really is shared across the family. One difference that matters for transport.py: the HID report descriptor contains no Report ID item, so on Linux hidraw a write must be 321 bytes -- a leading 0x00 report-number byte plus the 320-byte payload. Worth dumping /sys/class/hidraw/hidrawN/device/report_descriptor on an Orion to see whether the same applies there. Full descriptor for this device: 06 a0 ff 09 01 a1 01 09 02 a1 00 06 a1 ff 09 03 09 04 15 80 25 7f 35 00 45 ff 75 08 96 40 01 81 02 09 05 09 06 15 80 25 7f 35 00 45 ff 75 08 96 40 01 91 02 c0 c0\",\n    \"evidence\": \"sysfs report_descriptor and endpoint attributes\"\n  },\n  \"protocol\": {\n    \"streams_state_unprompted\": false,\n    \"supports_control_get_report\": false,\n    \"has_readback\": false,\n    \"status\": \"confirmed\",\n    \"notes\": \"THIS IS THE BIG BEHAVIOURAL DIFFERENCE FROM ORION. Orion streams its state report every 4 ms, so a client can simply read. This device sends nothing at all until it is written to, and a HID GET_REPORT control transfer is stalled (EPIPE). There is currently no way to read device state back. Every param below was therefore confirmed by sending a frame and reading the result off the unit's own front panel display, not from the wire. A client written against Orion's passive-read model will not work here.\",\n    \"evidence\": \"90 s passive listen, HID GET_REPORT, and an active ALSA capture stream -- all produced zero control traffic\"\n  },\n  \"frame\": {\n    \"command\": {\n      \"magic_offset\": 0,\n      \"magic\": \"0x70\",\n      \"opcode_offset\": 4,\n      \"opcode\": \"0x13\",\n      \"opcode_name\": \"SET_PARAM\",\n      \"param_id_offset\": 16,\n      \"channel_offset\": 17,\n      \"value_offset\": 18,\n      \"status\": \"confirmed\",\n      \"notes\": \"Same field layout as Orion Studio III. One nuance: byte 0 is NOT a discriminator on this device -- sweeping all 256 values at offset 0 with the opcode held at 0x00 produced an identical rejection every time. 0x70 is written there for family consistency but the device ignores it. Offset 4 is the real discriminator.\",\n      \"evidence\": \"eight distinct gain values sent to channels 0..7, each read back on the front panel\"\n    },\n    \"state_report\": {\n      \"status\": \"unconfirmed\",\n      \"notes\": \"Base offsets are NOT filled in, deliberately. parse_state() reads gain_base_offset, status_base_offset and status_bits without consulting status, so putting numbers there would make `status` report a gain and a phantom state that no one has checked against a real frame. The numbers below are good enough to be worth having and not good enough to act on. They are listed in unresolved_state_offsets.\",\n      \"evidence\": \"live device readback, 2026-09-01\"\n    },\n    \"response_frame\": {\n      \"magic_offset\": 0,\n      \"magic\": \"0x61\",\n      \"status_offset\": 4,\n      \"status_values\": { \"0x10\": \"unknown opcode\" },\n      \"status\": \"confirmed\",\n      \"notes\": \"Sent only in response to an unrecognised opcode. A recognised opcode is answered with silence. Careful: silence means the opcode was recognised, not that it took effect -- opcode 0x14 is silent and does nothing.\",\n      \"evidence\": \"alternating control test: 0x00 replies, 0x13 and 0x14 silent, with the interleaved 0x00 replies proving the endpoint stayed alive\"\n    }\n  },\n  \"opcodes\": {\n    \"0x13\": { \"name\": \"SET_PARAM\", \"status\": \"confirmed\" },\n    \"0x14\": { \"name\": \"SET_LINK?\", \"status\": \"recognised, no observed effect\" },\n    \"0x01\": { \"name\": null, \"status\": \"forbidden\", \"reason\": \"wedges the USB controller, see hazards\" },\n    \"0x02\": { \"name\": null, \"status\": \"forbidden\", \"reason\": \"wedges the USB controller, see hazards\" }\n  },\n  \"channels\": {\n    \"addressing\": \"0-indexed, written to frame.command.channel_offset\",\n    \"count\": 8,\n    \"max_safe_index\": 7,\n    \"hiz_channels\": [\n      0,\n      1\n    ],\n    \"status\": \"confirmed\",\n    \"notes\": \"Eight hybrid preamps. An index above max_safe_index does not get ignored -- it crashes the firmware, see hazards.channel_index_out_of_range. Hi-Z exists only on channels 1 and 2 (indices 0 and 1); the device accepts input_mode=hiz on any channel and displays it on its own panel with no circuit behind it, so the client has to enforce this.\",\n    \"evidence\": \"eight distinct gain values, one per channel, all read back on the front panel\"\n  },\n  \"buses\": {\n    \"addressing\": \"bus id written to frame.command.channel_offset, the same byte that carries a channel index for per-channel params\",\n    \"known\": {\n      \"0\": { \"name\": \"monitor_1\", \"aliases\": [\"monitor\", \"mon1\"], \"verified\": true },\n      \"1\": { \"name\": \"headphone_1\", \"aliases\": [\"hp1\"], \"verified\": true },\n      \"2\": { \"name\": \"headphone_2\", \"aliases\": [\"hp2\"], \"verified\": true },\n      \"5\": { \"name\": \"monitor_2\", \"aliases\": [\"mon2\", \"reamp\"], \"verified\": false }\n    },\n    \"status\": \"confirmed\",\n    \"notes\": \"The id scheme does match Orion Studio III's after all. Ids 0, 1 and 2 were each driven to a distinct level and read back. Id 5 was accepted the same way but Monitor 2 is not readable from the front panel, so it stays unverified.\",\n    \"evidence\": \"four distinct levels on four bus ids, read back on the front panel\"\n  },\n  \"params\": {\n    \"input_mode\": {\n      \"id\": \"0x4f\",\n      \"status\": \"confirmed\",\n      \"type\": \"enum\",\n      \"values\": { \"0\": \"mic\", \"1\": \"line\", \"2\": \"hiz\" },\n      \"forbidden_values\": [\"3\"],\n      \"notes\": \"Same param id as Orion, but the VALUE SET IS NOT THE SAME. Orion defines 3 = direct. This device has no direct mode and sending 3 crashes its firmware -- see hazards.forbidden_enum_values. The product manual independently confirms only mic / line / Hi-Z.\",\n      \"evidence\": \"each value set on a different channel and read back on the front panel; value 3 crashed the unit\"\n    },\n    \"gain\": {\n      \"id\": \"0x50\",\n      \"status\": \"confirmed\",\n      \"type\": \"int8\",\n      \"encoding\": \"two's complement, dB\",\n      \"per_mode_range\": { \"mic\": [-12, 65], \"line\": [-6, 20], \"hiz\": [0, 40] },\n      \"device_side_clamping\": true,\n      \"notes\": \"Same param id as Orion, but the ranges differ except for line. Orion has mic 0..75 and hiz 0..65; this device is mic -12..65 and hiz 0..40. The device clamps to the current input_mode's range rather than rejecting an out-of-range value, which is what made the bounds measurable without a capture.\",\n      \"evidence\": \"deliberate over-range values in each mode clamped to exactly these six bounds, read off the front panel\"\n    },\n    \"phantom\": {\n      \"id\": \"0x51\",\n      \"status\": \"confirmed\",\n      \"type\": \"bool\",\n      \"constraint\": \"mic mode only\",\n      \"notes\": \"48V into a ribbon microphone destroys it. A client must never assert this without knowing what is connected.\",\n      \"evidence\": \"set on two channels only; 48V lit on exactly those two and stayed dark on the rest\"\n    },\n    \"phase_invert\": {\n      \"id\": \"0x52\",\n      \"status\": \"confirmed\",\n      \"type\": \"bool\",\n      \"evidence\": \"set on three channels only; the indicator lit on exactly those three and stayed dark on the rest\"\n    },\n    \"bus_level\": {\n      \"id\": \"0x47\",\n      \"status\": \"confirmed\",\n      \"type\": \"int\",\n      \"applies_to\": \"buses\",\n      \"encoding\": \"value N sets the bus to -N dB\",\n      \"notes\": \"Same param id as Orion, DIFFERENT SCALE. Orion encodes 0..96 with 96 (0x60) meaning 0 dB unity. Here the value is simply negated decibels: 30 gives -30 dB. The same byte therefore means about -66 dB on Orion and -30 dB here. This is the second place where an inherited param id carries a different encoding.\",\n      \"evidence\": \"bus 0 sent 30 showed -30 dB; then buses 0/1/2/5 sent 60/45/55/50 and the matching outputs followed\"\n    },\n    \"bus_mute\": {\n      \"id\": \"0x48\",\n      \"status\": \"confirmed\",\n      \"type\": \"bool\",\n      \"applies_to\": \"buses\",\n      \"evidence\": \"set on one bus only; that bus muted and the others did not\"\n    },\n    \"bus_dim\": {\n      \"id\": \"0x68\",\n      \"status\": \"unconfirmed\",\n      \"type\": \"bool\",\n      \"applies_to\": \"buses\",\n      \"notes\": \"Your Orion id, carried over as a candidate. Accepted by the device but no dim state appears on the front panel. Three readings remain open: wrong id here, no panel indicator for dim, or no dim on this model. Needs a capture.\",\n      \"evidence\": \"sent, silent, no observable change\"\n    },\n    \"bus_mono\": {\n      \"id\": \"0x69\",\n      \"status\": \"unconfirmed\",\n      \"type\": \"bool\",\n      \"applies_to\": \"buses\",\n      \"notes\": \"Your Orion id, carried over as a candidate. Accepted, but this front panel displays no mono/stereo state at all, so it is untestable by eye. Not evidence either way.\",\n      \"evidence\": \"sent, silent, nothing to observe\"\n    },\n    \"channel_link\": {\n      \"id\": null,\n      \"status\": \"unconfirmed\",\n      \"type\": \"per-pair bool\",\n      \"notes\": \"The feature exists -- the manual documents a Link button that mirrors changes onto the neighbouring channel -- and opcode 0x14 is recognised by the device. But neither your frame.link_command layout (param_id 0xa2 at 16, pair_index at 18, enabled at 19) nor a SET_PARAM-style layout (pair_index at 17, enabled at 18) actually links a pair. This is the clearest case where an Orion frame shape does not transfer, and the best target for the next capture.\",\n      \"evidence\": \"controlled test: both channels set to 10 dB, pair linked with both layouts, then only one channel moved -- the other stayed put\"\n    }\n  },\n  \"hazards\": {\n    \"_comment\": \"Proposed addition to the profile schema. This device has no bounds checking of its own and faults in ways that cost a physical power cycle of the unit. Happy to move or drop this block if you would rather keep it out of the profiles.\",\n    \"channel_index_out_of_range\": {\n      \"rule\": \"clamp the channel index to channels.max_safe_index before writing\",\n      \"effect\": \"firmware BusFault; the front panel shows 'critical error L204 busfault handler' and only a physical power cycle recovers it\",\n      \"notes\": \"An ARM Cortex-M BusFault is raised on an invalid memory access, so the firmware is indexing its per-channel array unchecked. Note that the same byte carries bus ids for bus params, where 0/1/2/5 are legal -- bound-check against the right address space for the param being sent, not one global channel count.\"\n    },\n    \"forbidden_enum_values\": {\n      \"rule\": \"validate every enum value against this device's own profile; never pass one through from another device's profile or from user input\",\n      \"effect\": \"input_mode = 3 crashes the firmware and needs a physical power cycle\",\n      \"notes\": \"This is the concrete reason a shared profile format must not let one device's enum leak into another's.\"\n    },\n    \"wedging_opcodes\": {\n      \"opcodes\": [\"0x01\", \"0x02\"],\n      \"rule\": \"send only opcodes from a confirmed allow-list, never a value taken from user input, and rate-limit writes\",\n      \"effect\": \"the USB controller wedges; every further write returns ETIMEDOUT, the device then drops off the bus with 'device descriptor read/64, error -71', and neither a driver rebind nor the kernel's own port power cycle recovers it. Only unplugging the unit's power does.\",\n      \"notes\": \"Which of the two is responsible was not isolated, because narrowing it down costs another physical power cycle. Both are treated as forbidden. The unit's front panel display glitches at the same moment, which suggests the control channel and the display share one processor.\"\n    }\n  },\n  \"unresolved_state_offsets\": [\n    \"state_report base offsets, derived from Antelope's declared 0x73 layout but NOT yet verified against a raw frame: gain_base_offset 33 (byte * 8), status_base_offset 41 (one byte per preamp, count 8), volumes_and_mutes at offset 28, stride 1, count 5 (volume in the low 7 bits, mute in the top bit).\",\n    \"status_bits from the same source: type mask 0x0f shift 0, phantom 0x10 shift 4, hpf 0x20 shift 5, phase_inv 0x40 shift 6, zero_cross 0x80 shift 7.\"\n  ]\n}\n";

