static ORION_STUDIO_SC_FRAME_11_FIELDS_20_CHILDREN: &[FrameFieldDefinition] = &[
    FrameFieldDefinition { name: "0x00", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "device id + firmware (ascii '4.41' seen)", children: &[] },
    FrameFieldDefinition { name: "0x01", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "model name ('OrionStudio_III') + serial + hw rev ('7.0') -- CONTAINS THE DEVICE SERIAL, do not commit raw dumps", children: &[] },
    FrameFieldDefinition { name: "0x02", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "per-channel present flag (scalar 0x01), indexed 0..63", children: &[] },
    FrameFieldDefinition { name: "0x03", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "ROUTING MATRIX -- one record per destination group, index = dest_id 0..14. Record = <dest_id> then a (source_bank, source_index) pair per output channel of that group (destination_channels[dest_id] pairs), identical layout to the frame.routing_command write frame. VERIFIED byte-identical against CLI-written routes 2026-08-31.", children: &[] },
    FrameFieldDefinition { name: "0x04", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "VIRTUAL MIXER -- one record per mix, index = mix number 0..3 (= Mix 1..4). Record = a flat array of 33 three-byte slots, SAME field order as the frame.mix_command write frame: <fader> <pan|mute|solo> <send>. Slot index maps 1:1 onto frame.mix_command's `channel` field with NO special case: slot 0 = the MIX MASTER strip, slots 1..32 = the 32 input strips. 99 bytes on the wire, zero-padded to the report size. DECODED + HARDWARE-CONFIRMED, both halves. (a) INPUTS, 2026-08-31: wrote mix 1 / ch 5 / fader 40 / pan +12 / mute / send 33 (frame bytes `28 6c 21`), read the record back and slot 5 was `28 6c 21` with NO other slot changed; three reads 2.5s apart -- and later 142 reads over 150s -- were byte-identical, so the third byte is stored send state and not a live meter. (b) MASTER, 2026-09-01: a usbmon capture of the Launcher sweeping the Mix 1 master fader (captures/new/mix1-masterfaderplay.pcapng) is 68 frames, every one `d4 05 00 00 <fader> 20 60` -- mix 0, CHANNEL 0, pan and send constant; the sweep ended at fader 90 and slot 0 then read back as -90 dB. The Launcher itself addresses channel 0, so it is a normal target and NOT an out-of-range write. protocol.parse_mixer_record; CLI `mix-status`. This is the mixer readback that frame.mix_command's notes used to say did not exist -- it is not in the 0x73 state report, it is here.", children: &[] },
    FrameFieldDefinition { name: "0x05", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "PREAMP GAIN -- one plain byte per physical input channel = gain in dB (line/direct read 0). Independent copy of the 0x73 state report's gain array (state_report.gain_base_offset 49). DECODED + differential-write confirmed 2026-09-03 (`set-gain 7 33` -> byte [7] = 0x21, nothing else moved). protocol.parse_preamp_gain_record; selftest cross-checks it against 0x73.", children: &[] },
    FrameFieldDefinition { name: "0x06", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "CHANNEL STATUS -- one byte per physical input channel, SAME packing as the 0x73 state report status array (state_report.status_base_offset 61 / status_bits): (phase_invert<<6)|(phantom<<4)|(mode&0x03). DECODED + differential-write confirmed 2026-09-03 (`set-invert 7 on` -> byte [7]=0x40; `set-mode 7 line` -> 0x41; phantom bit 0x10 follows the same shared encoding, not re-exercised -- no +48V on the reference unit during the sweep). protocol.parse_channel_status_record.", children: &[] },
    FrameFieldDefinition { name: "0x07", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "EQ / filter band data -- same `<freq LE16><Q LE16 x100><gain LE16 signed><mode>` stride as the surround per-speaker EQ (0x1a below, frame.surround_speaker). Records are HETEROGENEOUS (live-read 2026-09-04): idx 0 and idx 1 are 8 x a flat 5-band EQ (30/200/1k/5k/15k Hz, Q 0.71, gain 0, modes 0/2/2/2/1); idx 2 is 16 x a 19-byte record `01 <e803=1000> 0000 <2710=10000> 0000 ffff <64=100> 00000000 <18=24> 00` that looks like a per-band RANGE/capability descriptor, not live state. Purpose unresolved -- possibly a monitor/phones EQ or a capability table for the surround EQ. NOT a per-input-channel EQ (the Synergy Core has none -- input EQ is an AFX plugin). Not in the 0x74 connect walk, so no safe index bound above 0.", children: &[] },
    FrameFieldDefinition { name: "0x0a", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "AuraVerb parameters -- DECODED + HARDWARE-CONFIRMED 2026-09-03 (protocol.parse_auraverb_record). Single record (index 0). Layout: a 0x00 header byte, then four 11-byte blocks (Mix 1..4); the 43-byte record truncates block 4 to 9 bytes. Each block = the frame.auraverb_command payload minus its [18] mix byte: [0]room_size [1]color [2]pre_delay [3]0x64(wet const) [4]early_reflection_gain [5]late_reflection_delay [6]richness [7]reverb_time [8]reverb_level [9]enabled(01/00) [10]0xff(const). Decoded by differential readback -- set one param via `auraverb --<flag>`, re-read, see which byte moved; every param + the enable bit pinned this way and writing the pre-sweep values back reproduced the record byte-for-byte. CLI `auraverb` now live-reads this and does a verified read-modify-write; selftest.py t_auraverb / t_write_auraverb.", children: &[] },
    FrameFieldDefinition { name: "0x0b", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "in the 0x74 CONNECT WALK it is a section/phase marker (8 marker occurrences, index values 1/2/3/3/3/3/0/4), NOT an I/O category -- see frame.init_enumeration_report. A direct query at idx 0 answered with a scalar 0x01 in 2026-08 and with an EMPTY body on 2026-09-04, so treat it as structural, not state.", children: &[] },
    FrameFieldDefinition { name: "0x0c", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "~90-entry per-channel link/config table. Undecoded.", children: &[] },
    FrameFieldDefinition { name: "0x0d", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "scalar 0x18 (=24). Re-read 2026-09-04, same value. Meaning unknown; stable across reads so it is a constant or a slowly-changing capability, not live state. Not in the 0x74 connect walk (no safe index bound above 0).", children: &[] },
    FrameFieldDefinition { name: "0x11", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "S/PDIF + a capability bitmask block (128 bytes)", children: &[] },
    FrameFieldDefinition { name: "0x12", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "UNKNOWN. A 2026-08 probe saw a scalar; a direct query at idx 0 returned an EMPTY body on 2026-09-04. The old 'clock source or sample-rate index?' guess is RULED OUT -- both of those read back from the 0x73 state report instead (clock source @19, sample-rate index @18, rate in Hz @21-23), confirmed on hardware 2026-09-03/04. Not in the 0x74 connect walk, so no safe index bound above 0. NB: readback category 0x12 is NOT the same thing as command opcode 0x12 (SET_GLOBAL) -- see frame.readback.namespace_warning.", children: &[] },
    FrameFieldDefinition { name: "0x15", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "~90-entry table, sibling of 0x0c", children: &[] },
    FrameFieldDefinition { name: "0x16", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "UNKNOWN, ~8-16 bytes. NOT output trim and NOT pan law -- both ruled out 2026-09-03 by a live differential test: sweeping SET_PARAM 0x4b targets 0/1/2 (the confirmed output-trim targets) moved 0x73 [24]/[25] exactly as documented but left 0x16 untouched, and SET_PARAM 0x4b target 3 (the pan-law hypothesis) did nothing anywhere. Content seen: all-zero (2026-09-03), '00 00 00 32 00 00 00 32 01 12 00 01 01 12 00 01' (2026-09-01) -- so it does carry state sometimes; source unidentified (possibly transient / a webUI-touched value). Still undecoded.", children: &[] },
    FrameFieldDefinition { name: "0x1a", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "SURROUND PER-SPEAKER EQ readback -- the readback for the launcher-only 0x87/0xea frame (params.surround_speaker). 116 bytes = 4-byte header (`00 00 58 02`) + 16 EQ bands x 7 bytes, EXACT same layout as the write frame: `<freq LE16 Hz><Q LE16 x100><gain LE16 signed 0.01 dB><mode 0/1/2>`. One record per surround speaker, index 0..15 (this is what the 0x74 connect walk's `0x1a x16` actually is -- NOT ADAT; ADAT was a 16==16 count guess and has NO readback category, its gain/link is in 0x73 @75-90). LIVE-READ 2026-09-04: idx 0 == idx 1 both carried a non-flat low-frequency curve (bands clustered 30-600 Hz, cuts/boosts to +/-12 dB) = the room-correction curve the user had generated in 2.0 -- matches their observation that RC writes an identical curve to L and R. idx 2+ were flat default templates (Q 0.71, gain 0, the log-spaced 30 Hz..15 kHz band layout). So the surround EQ / Room Correction DOES have a readback after all. Not yet wired into a parser or the CLI.", children: &[] },
    FrameFieldDefinition { name: "0x1b", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "SURROUND GLOBAL readback -- the readback for the launcher-only 0xab/0xeb frame (params.surround_monitor). 1 record (idx 0). ALIGNMENT: body[N] == the 0xab write frame's byte [18+N], established 2026-09-04 by a live read against a known surround state, six independent field matches: body[0..1]=`02 9f` = frame[18][19] FORMAT 2.0; body[2]=`06` = frame[20] global delay (the 0.6 ms floor); body[4..5]=`58 02` = frame[22-23] LEVEL 600 = 0 dB; body[7..8]=`ff ff` = frame[25-26] per-speaker BYPASS mask, all active; body[9..10] = frame[27-28] MUTE mask; body[22..24]=`23 00 00` = frame[40-42], the documented bass-management marker. The 8-byte bass-management CHANNEL BLOCKS then start at body[25] = frame[43] exactly as field_map.23_onward_bass_mgmt says, and read back sensible values (LP 320 Hz / HP 80 Hz / fader 360 / order 2 on the 3 used channels, `[80][80][600][0]` defaults after) -- so this record INDEPENDENTLY CONFIRMS that byte map, which had been derived only from write captures. The earlier 'mixer bus level/range table' label was wrong: the repeating `50 00 50 00 58 02 00` that prompted it is the bass-management default channel block `[80][80][600][0]`, not bus levels. Parsed + wired 2026-09-04: protocol.parse_surround_global_record, CLI `surround-status`.", children: &[] },
    FrameFieldDefinition { name: "0x19", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "64 entries, all empty in the connect walk -- the 64-ch USB/TB stream slots", children: &[] },
    FrameFieldDefinition { name: "note", offset: None, stride: None, width: None, value: None, mask: None, values: &[], formula: "", text: "Categories 0x1c..0x60 answer but with empty bodies (probed 2026-08-31). Full raw enumeration: tools/readback_enum.py.", children: &[] },
];
