static ORION_STUDIO_SC_HAZARDS: &[HazardDefinition] = &[
    HazardDefinition { name: "blind_opcode_sweeps", status: Status::Confirmed, rule: "only send opcodes from constraints.allowed_opcodes; never a value from user input; rate-limit writes (constraints.min_write_interval_ms)", effect: "", notes: "Which of 0x01/0x02 is responsible was not isolated; both forbidden. An unmapped opcode could in principle reach a routine that writes non-volatile memory or enters recalibration -- nothing observed suggests that happened, nothing rules it out. This asymmetry is the whole argument against blind sweeps, including on Orion.", opcodes: &[], metadata: "{\"effect_on_discrete_8_pro\":\"opcodes 0x01 and 0x02 wedged the USB controller -- every further write ETIMEDOUT, the device dropped off the bus ('device descriptor read/64, error -71'), and NEITHER a driver rebind NOR the kernel port power-cycle recovered it. Only unplugging the unit's power did.\",\"enforced_by\":\"constraints.forbidden_opcodes + constraints.allowed_opcodes\",\"notes\":\"Which of 0x01/0x02 is responsible was not isolated; both forbidden. An unmapped opcode could in principle reach a routine that writes non-volatile memory or enters recalibration -- nothing observed suggests that happened, nothing rules it out. This asymmetry is the whole argument against blind sweeps, including on Orion.\",\"rule\":\"only send opcodes from constraints.allowed_opcodes; never a value from user input; rate-limit writes (constraints.min_write_interval_ms)\"}" },
    HazardDefinition { name: "channel_index_out_of_range", status: Status::Confirmed, rule: "bound-check the channel index against the RIGHT address space before writing -- constraints.channel_bounds (0-11) for gain/mode/phantom/phase, constraints.adat_channel_bounds (0-15) for adat_gain, constraints.bus_ids for bus params. Refuse, don't clamp-and-hope.", effect: "", notes: "Orion's CLI currently only warns past channels.confirmed_indices and sends anyway. Given the sibling behaviour that is too loose -- an out-of-range write should be refused unless --force. The same byte carries bus ids for bus params, where 0-5 are legal, so a single global channel-count check is wrong.", opcodes: &[], metadata: "{\"effect_on_discrete_8_pro\":\"an index above the channel count did NOT get ignored -- it raised an ARM Cortex-M BusFault ('critical error L204 busfault handler' on the panel) and needed a physical power cycle. The firmware indexes its per-channel array unchecked.\",\"enforced_by\":\"constraints.channel_bounds / constraints.adat_channel_bounds / constraints.bus_ids\",\"notes\":\"Orion's CLI currently only warns past channels.confirmed_indices and sends anyway. Given the sibling behaviour that is too loose -- an out-of-range write should be refused unless --force. The same byte carries bus ids for bus params, where 0-5 are legal, so a single global channel-count check is wrong.\",\"rule\":\"bound-check the channel index against the RIGHT address space before writing -- constraints.channel_bounds (0-11) for gain/mode/phantom/phase, constraints.adat_channel_bounds (0-15) for adat_gain, constraints.bus_ids for bus params. Refuse, don't clamp-and-hope.\"}" },
    HazardDefinition { name: "foreign_enum_values", status: Status::Confirmed, rule: "validate every enum value against THIS profile; never pass one through from another device's profile or straight from user input", effect: "", notes: "Orion does have input_mode 3 = direct (confirmed here), so this specific value is fine ON ORION -- the hazard is the general one: a shared profile format must not let one device's enum leak into another's code path.", opcodes: &[], metadata: "{\"effect_on_discrete_8_pro\":\"input_mode = 3 (Orion's 'direct') crashed the firmware and needed a physical power cycle -- that device has no direct mode.\",\"enforced_by\":\"constraints.input_mode_allowed_values\",\"notes\":\"Orion does have input_mode 3 = direct (confirmed here), so this specific value is fine ON ORION -- the hazard is the general one: a shared profile format must not let one device's enum leak into another's code path.\",\"rule\":\"validate every enum value against THIS profile; never pass one through from another device's profile or straight from user input\"}" },
];
